import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"1979年 · 高通胀警示与债券警告","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1979年.md","filePath":"05_quotes/by-year/1979年.md"}'),l={name:"05_quotes/by-year/1979年.md"};function u(s,e,c,q,_,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_1979年-·-高通胀警示与债券警告" tabindex="-1">1979年 · 高通胀警示与债券警告 <a class="header-anchor" href="#_1979年-·-高通胀警示与债券警告" aria-label="Permalink to &quot;1979年 · 高通胀警示与债券警告&quot;">​</a></h1><blockquote><p>管理经济业绩的主要检验标准，是实现投入资本的高收益率，而不是实现每股收益持续增长。我们认为，如果管理层和金融分析师把主要关注重点从每股收益和每股收益年度变化转移开，股东和公众才能更好理解很多企业。——巴菲特（49岁）</p></blockquote><p>本页收录1979年致股东信中的经典语录。这一年巴菲特罕见地讨论了通胀对投资者实际回报的侵蚀，提出著名的&quot;投资者痛苦指数&quot;，同时对长期债券发出深刻警告。ROE为18.6%。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>管理经济业绩的主要检验标准，是实现投入资本的高收益率，而不是实现每股收益持续增长。我们认为，如果管理层和金融分析师把主要关注重点从每股收益和每股收益年度变化转移开，股东和公众才能更好理解很多企业。</p></blockquote><blockquote><p>1964年9月30日每股账面价值19.46美元。1979年末，股权按市值计价的每股账面价值是335.85美元。账面价值增长年复利是20.5%。</p></blockquote><blockquote><p>就像原本3%的储蓄债券、5%的存折储蓄账户、8%的美国国债，在通胀作用下，最终都变成了在投资期限内吞噬、而不是提升购买力的金融工具，一家资本回报率20%的企业，在通胀条件下，只要通胀没比现在严重太多，就能给所有者带来负实际回报。</p></blockquote><blockquote><p>这种组合——通胀率加上所有者把企业年度收益拿到自己口袋需要支付的资本比例——可以叫做&quot;投资者痛苦指数&quot;。当这个指数超过企业股权回报率，投资者哪怕一分钱不消费，购买力也会缩水。</p></blockquote><blockquote><p>一家企业每股净资产年复利20%，几乎可以保证所有者获得非常成功的实际投资回报。现在这个结果看起来不那么确定了。</p></blockquote><blockquote><p>我们非常怀疑，在美元价值几乎肯定逐日缩水的世界里，以美元计价的长期固定利率债券还是不是合适的商业合同。</p></blockquote><blockquote><p>我们银行的经验：高成本运营的经理常常特别擅长找到新办法增加管理费用，而精打细算运营的经理即使成本已经远低于竞争对手，依然总能找到额外方法削减成本。</p></blockquote><blockquote><p>波洛尼厄斯的话（稍微改一下）：&quot;别做短期借款人，也别做长期贷款人。&quot;</p></blockquote><blockquote><p>我们告诉他们情况的时候，不想要公关文件，我们觉得你也不应该收到公关文件。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1979年是巴菲特执掌伯克希尔的第15个年头。这一年最大的背景是美国高通胀，巴菲特罕见地讨论了通胀对投资者实际回报的侵蚀，提出&quot;投资者痛苦指数&quot;：20%名义年收益在14%通胀下，税后购买力增长几乎为零。同时对长期债券发出警告：保险行业在长期债券上亏了大钱，长期固定利率债券不是合适的投资工具。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1979年-翻译-·-01-letters-1979年-核心总结-·-01-letters-1979年-思维导图" tabindex="-1"><a href="/01_letters/1979年/翻译">01_letters/1979年/翻译</a> · <a href="/01_letters/1979年/核心总结">01_letters/1979年/核心总结</a> · <a href="/01_letters/1979年/思维导图">01_letters/1979年/思维导图</a> <a class="header-anchor" href="#_01-letters-1979年-翻译-·-01-letters-1979年-核心总结-·-01-letters-1979年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1979年/翻译]] · [[→ 核心总结|01_letters/1979年/核心总结]] · [[→ 思维导图|01_letters/1979年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1979年/翻译">/01_letters/1979年/翻译</a></li></ul>',22)])])}const p=t(l,[["render",u]]);export{b as __pageData,p as default};
